@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@600&family=Open+Sans:wght@400;600;700&display=swap');
.kv{font-family:'Open Sans',sans-serif;font-size:16px;line-height:1.6;color:#454F5E;background:#EDF6EE;position:relative;width:100%;margin:0;overflow:hidden;-webkit-font-smoothing:antialiased}
.kv *{box-sizing:border-box}.kv h1,.kv h2,.kv h3,.kv p,.kv ul,.kv li{margin:0;padding:0}.kv ul{list-style:none}
.kv a{color:inherit;text-decoration:none;border:0;box-shadow:none}
.kv h1,.kv h2,.kv h3{font-family:'Playfair Display',serif;font-weight:600;line-height:1.2;text-transform:none;letter-spacing:0}
.kv .w{max-width:1180px;margin:0 auto;padding:0 24px}
.kv .bar{display:block;width:60px;height:3px;background:#0F172A;margin:18px 0 0}
.kv .btn{display:inline-block;padding:15px 30px;background:#1B9C85;color:#FFFFFF;font:700 13px/1 'Open Sans',sans-serif;letter-spacing:.08em;text-transform:uppercase;border:0;border-radius:5px;transition:.2s}.kv .btn:hover{background:#0F172A;color:#FFFFFF}
.kv .hero{position:relative;background:linear-gradient(90deg,#DCE2E4 0 50%,#EAEEEF 50% 100%);padding:150px 0 90px;color:#0F172A}
.kv .hero h1{color:#0F172A;font-size:clamp(34px,4.6vw,56px)}
.kv .hero .w{display:grid;grid-template-columns:1fr 1fr;gap:40px;align-items:center;position:relative}
.kv .hero .sub{margin-top:22px;font:700 18px/1.4 'Open Sans',sans-serif;color:#0F172A}
.kv .hero .lead{margin-top:14px;max-width:470px;opacity:.92}
.kv .hero .btn{margin-top:30px}
.kv .hero .ph{justify-self:end;width:min(100%,430px)}
.kv .hero .ph img{width:100%;height:auto;aspect-ratio:1/1;object-fit:cover;object-position:50% 20%;border-radius:20px;display:block;box-shadow:0 24px 50px rgba(0,0,0,.3)}
.kv .sec{padding:80px 0 90px;background:#EDF6EE}
.kv .sec.pre{padding-top:140px}
.kv .sec h2{font-size:clamp(28px,3.6vw,44px);text-align:center;color:#0F172A}
.kv .sec .bar{margin:18px auto 0;background:#0F172A}
.kv .sec .lead2{max-width:660px;margin:20px auto 0;text-align:center}
.kv .bl-g{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px;margin-top:44px}
.kv .bl-card{display:flex;flex-direction:column;min-width:0;background:#FFFFFF;border-radius:14px;overflow:hidden;box-shadow:0 14px 40px rgba(15,23,42,.12);transition:transform .2s}
.kv .bl-card:hover{transform:translateY(-4px)}
.kv .bl-cover{position:relative;display:block;aspect-ratio:3/2;overflow:hidden;background:linear-gradient(135deg,#1B9C85,#0F172A)}
.kv .bl-cover img{width:100%;height:100%;object-fit:cover;display:block}
.kv .bl-tag{position:absolute;top:14px;left:14px;padding:6px 14px;background:#1B9C85;color:#FFFFFF;font:700 11px/1.2 'Open Sans',sans-serif;letter-spacing:.12em;text-transform:uppercase}
.kv .bl-body{display:flex;flex-direction:column;flex:1;padding:22px 24px 26px}
.kv .bl-card time{display:block;margin-bottom:10px;font:700 13px/1 'Open Sans',sans-serif;letter-spacing:.06em;color:#178E79}
.kv .bl-card h3{font-size:19px;line-height:1.3;margin:0 0 12px;color:#0F172A}
.kv .bl-card h3 a:hover{color:#178E79}
.kv .bl-card p{margin:0 0 20px;font-size:16px;color:#454F5E}
.kv .bl-more{margin-top:auto;font:700 13px/1 'Open Sans',sans-serif;letter-spacing:.1em;text-transform:uppercase;color:#0F172A}
.kv .bl-more::after{content:" \2192"}.kv .bl-more:hover{color:#178E79}
.kv .all{text-align:center;margin-top:44px}
.kv .ft{background:#222222;color:rgba(255,255,255,.85);padding:70px 0 60px}
.kv .ft .w{display:grid;grid-template-columns:repeat(3,1fr);gap:40px}
.kv .ft h3{font-size:20px;margin-bottom:18px;color:#FFFFFF}
.kv .ft p,.kv .ft li{font-size:16px;margin-bottom:10px}
.kv .ft a{color:#7FE0CB}.kv .ft a:hover{color:#FFFFFF}
.kv .ft .copy{max-width:1180px;margin:44px auto 0;padding:24px 24px 0;border-top:1px solid rgba(255,255,255,.2);font-size:14px;opacity:.85}
